import re
import shutil
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("home-cameras")

RECORDINGS_ROOT = Path("/var/lib/homehub/recordings")
ARCHIVE_ROOT = Path("/var/lib/homehub/archive")
_CAMERA_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,63}$")
_ALLOWED_EXT = {".mp4", ".mkv", ".jpg"}


@mcp.tool()
def archive_camera_clip(camera_id: str, clip_filename: str) -> dict:
    if not camera_id or not _CAMERA_RE.match(camera_id):
        return {"ok": False, "error": "Invalid camera_id."}
    if not clip_filename or "/" in clip_filename or "\\" in clip_filename or clip_filename.startswith("."):
        return {"ok": False, "error": "Invalid clip_filename."}
    if Path(clip_filename).suffix.lower() not in _ALLOWED_EXT:
        return {"ok": False, "error": "Unsupported clip file type."}
    source = RECORDINGS_ROOT / camera_id / clip_filename
    if not source.is_file():
        return {"ok": False, "error": f"Clip not found for camera {camera_id}."}
    dest_dir = ARCHIVE_ROOT / camera_id
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / clip_filename
    if dest.exists():
        return {"ok": False, "error": "A clip with that name is already archived."}
    shutil.move(str(source), str(dest))
    return {"ok": True, "camera_id": camera_id, "archived_path": str(dest)}

import os
from datetime import datetime, timezone

import requests
from agents import function_tool

PUSHOVER_URL = "https://api.pushover.net/1/messages.json"
_PRI = {"info": -1, "warning": 0, "critical": 2}
_SND = {"info": "none", "warning": "pushover", "critical": "siren"}


@function_tool
def send_homeowner_device_alert(
    device_name: str,
    event: str,
    severity: str = "warning",
    room: str = "",
) -> dict:
    sev = (severity or "warning").lower()
    if sev not in _PRI:
        return {"sent": False, "error": f"Unknown severity '{severity}'."}
    dn = device_name.strip()
    ev = event.strip()
    if not dn or not ev:
        return {"sent": False, "error": "device_name and event are required."}

    ts = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    loc = f" in {room.strip()}" if room and room.strip() else ""
    msg = f"{dn}{loc}: {ev}\n{ts}"
    ttl = f"[{sev.upper()}] {dn}"

    p = {
        "token": os.environ["PUSHOVER_APP_TOKEN"],
        "user": os.environ["PUSHOVER_HOUSEHOLD_KEY"],
        "title": ttl[:250],
        "message": msg[:1024],
        "priority": _PRI[sev],
        "sound": _SND[sev],
    }
    if sev == "critical":
        p["retry"] = 60
        p["expire"] = 3600

    try:
        r = requests.post(PUSHOVER_URL, data=p, timeout=10)
    except requests.RequestException as e:
        return {"sent": False, "error": f"Network error: {e}"}

    if r.status_code != 200:
        return {"sent": False, "status": r.status_code, "error": r.text[:300]}

    b = r.json()
    if b.get("status") != 1:
        return {"sent": False, "error": "; ".join(b.get("errors", ["unknown error"]))}

    out = {"sent": True, "request_id": b.get("request"), "severity": sev}
    if "receipt" in b:
        out["receipt"] = b["receipt"]
    return out
